server {
    listen 80;
    listen [::]:80;
    server_name example.com;
    root /var/www/html;
    index index.html index.htm;
}

server {
    listen 8080;
    server_name dashboard.internal;
    root /srv/dashboard;
    index index.html;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    return 444;
}

server {
    listen 80;
    server_name shop.example.com;
    root /var/www/shop;
    index index.html;
}
server {
    listen 80;
    server_name blog.example.com;
    root /var/www/blog;
    index index.html;
}

server {
    listen 3000;
    server_name grafana.monitoring;
    root /usr/share/grafana/public;
    index index.html;
}

server {
    listen 80;
    server_name www.mysite.dev;
    root /opt/site;
    index home.html index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}

server {
    listen 80;
    server_name upload.example.com;
    root /var/www/uploads;
    client_max_body_size 2m;
    client_body_buffer_size 128k;
}

server {
    listen 80;
    server_name assets.example.com;
    root /var/www/assets;
    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
}

server {
    listen 80;
    server_name www.exemple.fr;
    root /var/www/fr;
    charset utf-8;
    index index.html;
}

server {
    listen 80;
    server_name www.errors.example;
    root /var/www/html;
    error_page 404 /404.html;
    error_page 502 503 504 /50x.html;
    location = /404.html {
        internal;
    }
    location = /50x.html {
        internal;
    }
}

server {
    listen 80 default_server;
    server_name _;
    root /var/www/default;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}

server {
    listen 80;
    server_name example.org www.example.org;
    root /var/www/example-org;
    index index.html;
}

server {
    listen 8000;
    server_name app.local;
    root /srv/app/public;
    access_log /var/log/nginx/app.access.log;
    error_log /var/log/nginx/app.error.log warn;
}

server {
    listen 80;
    server_name legacy.example.net;
    root /var/www/legacy;
    server_tokens off;
}

server {
    listen 80;
    listen 8080;
    server_name www.same-site.io;
    root /var/www/same-site;
    index index.html;
}

server {
    listen 80;
    server_name old.example.com;
    root /var/www/old;
    index index.html;
}

server {
    listen 80;
    server_name form.example.com;
    root /var/www/form;
    client_body_buffer_size 64k;
    client_body_timeout 30s;
    client_header_timeout 30s;
    send_timeout 30s;
}

server {
    listen 80;
    server_name _;
    location = /healthz {
        default_type text/plain;
        return 200 'OK';
    }
}

server {
    listen [::]:80 ipv6only=on;
    server_name v6.example.com;
    root /var/www/v6;
    index index.html;
}

server {
    listen 80;
    server_name www.behind-lb.example;
    root /var/www/app;
    absolute_redirect off;
    port_in_redirect off;
}
